BEGIN;
SELECT no_plan();
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"d1111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
SELECT lives_ok($$SELECT api.save_patient_initial_measurements('f1111111-1111-4111-8111-111111111111',CURRENT_DATE-10,'{"height_cm":170,"initial_weight_kg":75,"target_weight_kg":70}')$$,'Patient declares initial and target');
SELECT is((SELECT initial_weight_kg FROM api.patient_initial_measurements WHERE patient_id='f1111111-1111-4111-8111-111111111111'),75::numeric,'Initial value persisted');
SELECT throws_ok($$SELECT api.save_patient_initial_measurements('f1111111-1111-4111-8111-111111111111',CURRENT_DATE+1,'{}')$$,NULL,NULL,'Future rejected');
SELECT throws_ok($$SELECT api.save_patient_initial_measurements('f1111111-1111-4111-8111-111111111111',CURRENT_DATE,'{"height_cm":180}')$$,NULL,NULL,'Concurrent stale write rejected');
SELECT set_config('request.jwt.claims','{"sub":"b2222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
SELECT is((SELECT count(*) FROM api.patient_initial_measurements),1::bigint,'Assigned professional reads');
SELECT throws_ok($$SELECT api.save_patient_initial_measurements(patient_id,CURRENT_DATE,'{"target_weight_kg":65}',updated_at) FROM api.patient_initial_measurements$$,NULL,NULL,'Professional cannot choose patient target');
SELECT lives_ok($$SELECT api.save_patient_initial_measurements(patient_id,CURRENT_DATE,'{"height_cm":171,"initial_weight_kg":75,"target_weight_kg":70}',updated_at) FROM api.patient_initial_measurements$$,'Professional corrects baseline preserving target');
SELECT set_config('request.jwt.claims','{"sub":"d2222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
SELECT is((SELECT count(*) FROM api.patient_initial_measurements),0::bigint,'Other patient denied');
SELECT throws_ok($$SELECT api.save_patient_initial_measurements('f1111111-1111-4111-8111-111111111111',CURRENT_DATE,'{}')$$,NULL,NULL,'Other patient cannot write');
SELECT set_config('request.jwt.claims','{"sub":"a0000000-0000-4000-8000-000000000000","role":"authenticated"}',true);
SELECT is((SELECT count(*) FROM api.clinical_patient_profiles),0::bigint,'Admin denied clinical profile');
SELECT is((SELECT count(*) FROM api.patient_initial_measurements),0::bigint,'Admin denied measurements');
SELECT ok(NOT has_table_privilege('authenticated','app.patient_initial_measurements','UPDATE'),'No direct write');
SELECT * FROM finish();
ROLLBACK;
